def _navigation_section_group(primary: str, mode: str, secondary_key: str) -> str:
    if primary == "Knowledge":
        if secondary_key in {"customers", "contacts", "locations"}:
            return "Accounts"
        if secondary_key in {"vendors", "manufacturers", "products", "services"}:
            return "Commercial"
        if secondary_key in {"price_lists", "imports", "assemblies"}:
            return "Operations"
        return "Summary"
    if primary == "Transactions":
        if secondary_key in {
            "estimates",
            "proposals",
            "sales_orders",
            "change_orders",
        }:
            return "Sales"
        if secondary_key in {
            "purchase_orders",
            "rfqs",
            "vendor_quotes",
            "receiving",
        }:
            return "Procurement"
        if secondary_key in {"vendor_bills", "customer_invoices"}:
            return "Settlement"
        return "Overview"
    if primary == "Settings":
        if secondary_key in {"organization_settings", "personal_preferences"}:
            return "Active"
        return "Future"
    if primary != "Projects":
        return "Workspace"
    if mode == "library":
        if secondary_key in {
            "overview",
            "all_projects",
            "recent_projects",
            "pinned_projects",
            "archived_projects",
            "repository",
        }:
            return "Library"
        return "Actions"
    if secondary_key in {
        "overview",
        "documents",
        "bom_review",
        "scope_risk",
        "engineering_review",
        "estimate",
        "notebook",
        "reports",
    }:
        return "Review"
    if secondary_key == "project_details":
        return "Details"
    return "Settings"


def _group_navigation_sections(
    primary: str,
    mode: str,
    sections: list[dict[str, Any]],
) -> list[tuple[str, list[dict[str, Any]]]]:
    grouped: list[tuple[str, list[dict[str, Any]]]] = []
    current_group = ""
    current_sections: list[dict[str, Any]] = []
    for section in sections:
        group_name = _navigation_section_group(
            primary,
            mode,
            _safe_text(section.get("secondary_key"), ""),
        )
        if group_name != current_group:
            if current_sections:
                grouped.append((current_group, current_sections))
            current_group = group_name
            current_sections = [section]
            continue
        current_sections.append(section)
    if current_sections:
        grouped.append((current_group, current_sections))
    return grouped


