def _pending_upload_identity(name: str, data: bytes) -> str:
    normalized_name = _safe_text(name, "").strip().lower()
    source_hash = hashlib.sha1(data).hexdigest()
    return f"{normalized_name}|{len(data)}|{source_hash}"


