def _open_project_record(
    st: Any,
    record: ProjectWorkspaceRecord,
    workspace_service: ProjectWorkspaceService | None = None,
) -> None:
    _navigate_to_project_page(
        st,
        record=record,
        page="Overview",
        workspace_service=workspace_service,
    )


def _clear_create_project_widget_state(st: Any) -> None:
    for key in [
        "atlas_new_project_owner_lookup",
        "atlas_new_project_owner_selected",
        "atlas_new_project_name",
        "atlas_new_project_client",
        "atlas_new_project_bid_date",
        "atlas_new_project_location",
    ]:
        st.session_state.pop(key, None)
    _reset_create_project_upload_state(st)


def _navigate_to_project_page(
    st: Any,
    *,
    record: ProjectWorkspaceRecord,
    page: str,
    workspace_service: ProjectWorkspaceService | None = None,
) -> None:
    st.session_state["atlas_active_workspace_id"] = record.workspace_id
    st.session_state["atlas_active_page"] = page
    if workspace_service is not None and hasattr(workspace_service, "save_record"):
        workspace_service.save_record(record)
    if page == "Documents":
        _clear_create_project_widget_state(st)
    st.rerun()


def _project_review_status(
    record: ProjectWorkspaceRecord,
    manifest: dict[str, Any],
) -> str:
    readiness = _safe_text(record.review_summary.get("readiness_level"), "")
    if readiness:
        return readiness.replace("_", " ").title()
    review_artifacts = sum(
        int(value)
        for value in dict(manifest.get("review_artifact_counts") or {}).values()
    )
    if review_artifacts == 0:
        return "Not Started"
    return "Needs Review"


def _project_library_rows(
    workspace_service: ProjectWorkspaceService,
    *,
    include_archived: bool,
    limit: int = 500,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for record in workspace_service.list_workspaces(
        include_archived=include_archived,
        limit=limit,
    ):
        stakeholder_rows: list[dict[str, Any]] = []
        try:
            stakeholder_rows = list(
                workspace_service.list_project_stakeholders(record.workspace_id)
            )
        except Exception:
            stakeholder_rows = []
        manifest = workspace_service.read_manifest(record.workspace_id)
        document_count = sum(
            int(value) for value in dict(manifest.get("document_counts") or {}).values()
        )
        rows.append(
            {
                "record": record,
                "workspace_id": record.workspace_id,
                "atlas_bid_id": _atlas_bid_id(record),
                "project_name": record.project.name,
                "customer": _safe_text(
                    record.metadata.get("owner"), record.project.client
                ),
                "stakeholder_names": " | ".join(
                    [
                        _safe_text(record.metadata.get("owner"), record.project.client),
                        _safe_text(record.metadata.get("consultant"), ""),
                        _safe_text(record.metadata.get("architect"), ""),
                        " | ".join(
                            [
                                _safe_text(
                                    item.get("organization_display_name"),
                                    "",
                                )
                                for item in stakeholder_rows
                            ]
                        ),
                        " | ".join(
                            [
                                " ".join(
                                    [
                                        _safe_text(alias, "")
                                        for alias in list(
                                            item.get("organization_aliases") or []
                                        )
                                    ]
                                )
                                for item in stakeholder_rows
                            ]
                        ),
                        ", ".join(
                            [
                                _safe_text(item, "")
                                for item in list(record.metadata.get("engineers") or [])
                                if _safe_text(item, "")
                            ]
                        ),
                    ]
                ),
                "client_project_number": _client_project_number(record),
                "internal_project_number": _internal_project_number(record),
                "lifecycle_stage": _safe_text(
                    record.metadata.get("lifecycle_stage"),
                    _project_stage(record),
                )
                .replace("_", " ")
                .title(),
                "current_status": _safe_text(
                    record.metadata.get("status"),
                    record.project.status.value,
                )
                .replace("_", " ")
                .title(),
                "last_opened": _safe_text(
                    record.last_opened_at,
                    _safe_text(record.metadata.get("last_opened"), "n/a"),
                ),
                "last_modified": _safe_text(
                    record.metadata.get("last_modified"),
                    record.updated_at,
                ),
                "document_count": document_count,
                "review_status": _project_review_status(record, manifest),
                "reference": record.is_reference,
                "archived": record.archived,
                "pinned": record.pinned,
                "source": record.source_label,
            }
        )
    return rows


def _open_project_from_local_path(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    path_text: str,
) -> None:
    path = Path(path_text).expanduser()
    if not path.exists():
        st.error(f"Path not found: {path}")
        return

    if path.is_dir() and (path / "project.json").exists():
        _open_project_record(
            st,
            workspace_service.load_record(path / "project.json"),
            workspace_service,
        )
        return

    if path.is_dir() and (path / "workspace.json").exists():
        _open_project_record(
            st,
            workspace_service.load_record(path / "workspace.json"),
            workspace_service,
        )
        return

    if path.name in {"workspace.json", "project.json", "metadata.json"}:
        _open_project_record(st, workspace_service.load_record(path), workspace_service)
        return

    if path.name == "intake_snapshot.json":
        context = build_intake_review_context(path)
        record = _build_record_from_context(context)
        workspace_service.save_record(record)
        _open_project_record(st, record, workspace_service)
        return

    if path.is_dir():
        context = build_reference_project_context(path)
        record = _build_record_from_context(context)
        workspace_service.save_record(record)
        _open_project_record(st, record, workspace_service)
        return

    st.error(
        "Open a project.json/workspace.json file, intake_snapshot.json file, or project folder."
    )


def _render_global_search_control(st: Any, host: Any) -> None:
    _hydrate_global_search_input_state(st)
    host.text_input(
        "Search",
        key=_global_search_widget_key(st),
        placeholder="Search",
        label_visibility="collapsed",
        on_change=_submit_global_search,
        args=(st,),
    )


def _submit_global_search(st: Any) -> None:
    query = _normalize_global_search_query(_global_search_input_value(st))
    if not _is_meaningful_global_search_query(query):
        return
    st.session_state["atlas_global_search_query"] = query
    st.session_state["atlas_global_search_last_submitted"] = query


def _open_page(st: Any, page: str) -> None:
    st.session_state["atlas_active_page"] = page
    st.rerun()


def _format_recent_opened_at(timestamp: str | None) -> str:
    normalized = _safe_text(timestamp, "")
    if not normalized:
        return "n/a"
    try:
        parsed = datetime.fromisoformat(normalized.replace("Z", "+00:00"))
    except Exception:
        return normalized
    return parsed.strftime("%b %d, %Y %H:%M")


def _top_navigation_groups(
    record: ProjectWorkspaceRecord | None,
) -> list[tuple[str, list[tuple[str, str]]]]:
    if record is None:
        return APPLICATION_NAV_GROUPS
    return [APPLICATION_NAV_GROUPS[0], *PROJECT_NAV_GROUPS]


def _knowledge_secondary_state_key() -> str:
    return "atlas_knowledge_secondary_group"


def _knowledge_tertiary_state_key() -> str:
    return "atlas_knowledge_tertiary_page"


def _knowledge_navigation_defaults(st: Any) -> None:
    st.session_state.setdefault(_knowledge_secondary_state_key(), "Knowledge Overview")
    st.session_state.setdefault(_knowledge_tertiary_state_key(), "Summary")


def _knowledge_secondary_group_for_page(page: str) -> str:
    return KNOWLEDGE_SECONDARY_BY_PAGE.get(page, "Knowledge Overview")


def _knowledge_tertiary_page_for_kind(kind: str) -> str:
    return KNOWLEDGE_TERTIARY_BY_KIND.get(kind, "Summary")


def _knowledge_tertiary_page_for_route(page: str) -> str:
    return KNOWLEDGE_TERTIARY_BY_PAGE.get(page, "Summary")


def _set_knowledge_navigation_selection(
    st: Any,
    *,
    page: str | None = None,
    kind: str | None = None,
) -> None:
    if page is not None:
        st.session_state[_knowledge_secondary_state_key()] = (
            _knowledge_secondary_group_for_page(page)
        )
        st.session_state[_knowledge_tertiary_state_key()] = (
            _knowledge_tertiary_page_for_route(page)
        )
    if kind is not None:
        st.session_state[_knowledge_tertiary_state_key()] = (
            _knowledge_tertiary_page_for_kind(kind)
        )
        st.session_state[_knowledge_secondary_state_key()] = (
            _knowledge_secondary_group_for_page(_knowledge_tertiary_page_for_kind(kind))
        )


def _knowledge_content_view_from_shell(st: Any) -> str:
    primary = _safe_text(st.session_state.get(_navigation_primary_state_key()), "")
    secondary = _safe_text(st.session_state.get(_navigation_secondary_state_key()), "")
    tertiary = _safe_text(st.session_state.get(_navigation_tertiary_state_key()), "")
    if primary != "Knowledge":
        return _safe_text(
            st.session_state.get(_knowledge_tertiary_state_key()), "Summary"
        )

    if secondary == "overview":
        if tertiary == "data_health":
            return "Commercial Health"
        if tertiary == "recent_activity":
            return "Import History"
        return "Summary"

    secondary_to_view = {
        "customers": "Customers",
        "contacts": "Contacts",
        "locations": "Locations",
        "vendors": "Vendors",
        "manufacturers": "Manufacturers",
        "products": "Products",
        "services": "Services",
        "price_lists": "Price Lists",
        "assemblies": "Assemblies",
    }
    if secondary in secondary_to_view:
        return secondary_to_view[secondary]
    if secondary == "imports":
        if tertiary in {"completed", "activity", "import_history"}:
            return "Import History"
        return "Imports"
    return _safe_text(st.session_state.get(_knowledge_tertiary_state_key()), "Summary")


def _sync_knowledge_content_state(st: Any) -> str:
    _knowledge_navigation_defaults(st)
    active_view = _knowledge_content_view_from_shell(st)
    st.session_state[_knowledge_secondary_state_key()] = (
        _knowledge_secondary_group_for_page(active_view)
    )
    st.session_state[_knowledge_tertiary_state_key()] = active_view
    return active_view


def _render_knowledge_navigation_frame(st: Any) -> None:
    _knowledge_navigation_defaults(st)
    active_secondary = _safe_text(
        st.session_state.get(_knowledge_secondary_state_key()),
        "Knowledge Overview",
    )
    active_tertiary = _safe_text(
        st.session_state.get(_knowledge_tertiary_state_key()),
        "Summary",
    )

    st.markdown("### Knowledge Navigation")
    st.caption(f"Secondary: {active_secondary} · Tertiary: {active_tertiary}")
    secondary_cols = st.columns([1.1, 1.1, 1.1])
    for column, (group_name, pages) in zip(secondary_cols, KNOWLEDGE_SECONDARY_GROUPS):
        is_active = group_name == active_secondary or active_tertiary in pages
        if column.button(
            group_name,
            key=f"atlas_knowledge_secondary_{group_name}",
            type="primary" if is_active else "secondary",
            width="stretch",
        ):
            st.session_state[_knowledge_secondary_state_key()] = group_name
            if pages:
                st.session_state[_knowledge_tertiary_state_key()] = pages[0]
            st.rerun()

    selected_pages = next(
        (
            pages
            for group_name, pages in KNOWLEDGE_SECONDARY_GROUPS
            if group_name == active_secondary
        ),
        list(KNOWLEDGE_TERTIARY_BY_PAGE.values()),
    )
    tertiary_columns = st.columns(max(1, len(selected_pages)))
    for column, page in zip(tertiary_columns, selected_pages):
        if column.button(
            page,
            key=f"atlas_knowledge_tertiary_{page}",
            type="primary" if page == active_tertiary else "secondary",
            width="stretch",
        ):
            st.session_state[_knowledge_tertiary_state_key()] = page
            st.session_state[_knowledge_secondary_state_key()] = (
                _knowledge_secondary_group_for_page(page)
            )
            st.rerun()


