def _secondary_key_for_page(primary: str, mode: str, page: str) -> str | None:
    if primary == "Knowledge":
        page_map = {
            "Knowledge": "overview",
            "Summary": "overview",
            "Commercial Health": "overview",
            "Customers": "customers",
            "Contacts": "contacts",
            "Locations": "locations",
            "Vendors": "vendors",
            "Manufacturers": "manufacturers",
            "Products": "products",
            "Services": "services",
            "Price Lists": "price_lists",
            "Imports": "imports",
            "Import History": "imports",
            "Assemblies": "assemblies",
        }
        return page_map.get(page, "overview")

    if primary != "Projects":
        if primary == "Transactions":
            return "overview" if page == "Transactions" else None
        if primary == "Settings":
            if page == "Administration":
                return "organization_settings"
            return None
        return None
    if mode == "library":
        page_map = {
            "Projects": "all_projects",
            "Pinned Projects": "pinned_projects",
            "Reference Projects": "repository",
            "Recent Projects": "recent_projects",
            "Create New Project": "create_project",
            "Open Existing Project": "repository",
        }
        return page_map.get(page, "overview")

    page_map = {
        "Overview": "overview",
        "Documents": "documents",
        "Processing": "processing",
        "BOM Review": "bom_review",
        "Scope & Risk": "scope_risk",
        "Engineering Review": "engineering_review",
        "Estimate": "estimate",
        "Notebook": "notebook",
        "Reports": "reports",
        "Drawings": "project_details",
        "Specifications": "project_details",
        "Equipment": "project_details",
        "Systems": "project_details",
        "Evidence": "project_details",
        "Relationships": "project_details",
        "Timeline": "project_details",
        "Project Metadata": "project_settings",
        "Repository": "project_settings",
        "Workspace Settings": "project_settings",
    }
    return page_map.get(page, "overview")


def _active_primary_workspace(page: str, record: ProjectWorkspaceRecord | None) -> str:
    if page == "Knowledge":
        return "Knowledge"
    if page == "Transactions":
        return "Transactions"
    if page in PROJECTS_LIBRARY_PAGES or page in PROJECTS_ACTIVE_PAGES:
        return "Projects"
    if record is not None and page not in {"Mission Control", "Administration"}:
        return "Projects"
    if page == "Reports":
        return "Reports"
    if page == "Administration":
        return "Settings"
    return "Atlas"


def _active_workspace_mode(page: str, record: ProjectWorkspaceRecord | None) -> str:
    if page == "Knowledge":
        return "application"
    if page == "Transactions":
        return "application"
    if page in PROJECTS_LIBRARY_PAGES:
        return "library"
    if page in PROJECTS_ACTIVE_PAGES:
        return "active"
    if record is not None and page not in {"Mission Control", "Administration"}:
        return "active"
    return "application"


def _sync_workspace_navigation_state(
    st: Any,
    record: ProjectWorkspaceRecord | None,
) -> None:
    page = _safe_text(st.session_state.get("atlas_active_page"), "Mission Control")
    primary = _active_primary_workspace(page, record)
    mode = _active_workspace_mode(page, record)
    st.session_state[_navigation_primary_state_key()] = primary
    st.session_state[_navigation_mode_state_key()] = mode

    selection = dict(st.session_state.get("atlas_context_selection") or {})
    selection_kind = _safe_text(selection.get("kind"), "")
    selection_data = dict(selection.get("data") or {})
    st.session_state[_navigation_selected_entity_type_key()] = selection_kind
    st.session_state[_navigation_selected_entity_id_key()] = _safe_text(
        _object_id_for_selection(selection_kind, selection_data),
        "",
    )

    if primary not in {"Knowledge", "Projects", "Transactions", "Settings"}:
        return

    sections = _workspace_navigation_contract(primary, mode)
    if not sections:
        return

    active_secondary = _safe_text(
        st.session_state.get(_navigation_secondary_state_key()),
        _safe_text(sections[0].get("secondary_key"), ""),
    )
    derived_secondary = _safe_text(_secondary_key_for_page(primary, mode, page), "")
    if (
        primary == "Knowledge"
        and page == "Knowledge"
        and selection_kind in _knowledge_selection_kinds()
    ):
        derived_secondary = _safe_text(
            _secondary_key_for_page(
                "Knowledge",
                "application",
                _knowledge_tertiary_page_for_kind(selection_kind),
            ),
            derived_secondary,
        )
    if derived_secondary and not (primary == "Transactions" and page == "Transactions"):
        active_secondary = derived_secondary

    section = next(
        (
            item
            for item in sections
            if _safe_text(item.get("secondary_key"), "") == active_secondary
        ),
        sections[0],
    )
    st.session_state[_navigation_secondary_state_key()] = _safe_text(
        section.get("secondary_key"),
        "",
    )

    actions = list(section.get("supported_tertiary_actions") or [])
    default_tertiary = _safe_text(
        section.get("default_tertiary_action"),
        _safe_text(actions[0].get("tertiary_key"), "") if actions else "",
    )
    active_tertiary = _safe_text(
        st.session_state.get(_navigation_tertiary_state_key()),
        default_tertiary,
    )
    if actions and active_tertiary not in {
        _safe_text(item.get("tertiary_key"), "") for item in actions
    }:
        active_tertiary = default_tertiary
    st.session_state[_navigation_tertiary_state_key()] = active_tertiary


def _tertiary_action_requires_selection(
    st: Any,
    action: dict[str, Any],
    record: ProjectWorkspaceRecord | None,
) -> bool:
    required = _safe_text(action.get("required_selection"), "")
    if required == "project":
        return record is None
    if required == "entity":
        return not _safe_text(
            st.session_state.get(_navigation_selected_entity_id_key()), ""
        )
    return False


def _render_workspace_navigation(
    st: Any,
    record: ProjectWorkspaceRecord | None,
) -> None:
    primary = _safe_text(
        st.session_state.get(_navigation_primary_state_key()),
        "Atlas",
    )
    mode = _safe_text(
        st.session_state.get(_navigation_mode_state_key()),
        "application",
    )
    sections = _workspace_navigation_contract(primary, mode)
    if not sections:
        return

    grouped_sections = _group_navigation_sections(primary, mode, sections)
    shell_cols = st.columns([1.25, 4.75])
    with shell_cols[0]:
        for group_index, (group_name, section_group) in enumerate(grouped_sections):
            if group_index > 0:
                st.markdown("---")
            st.caption(group_name.upper())
            for section in section_group:
                secondary_key = _safe_text(section.get("secondary_key"), "")
                is_active = secondary_key == _safe_text(
                    st.session_state.get(_navigation_secondary_state_key()),
                    "",
                )
                if st.button(
                    _safe_text(section.get("label"), secondary_key),
                    key=f"atlas_secondary_{primary}_{mode}_{secondary_key}",
                    type="primary" if is_active else "secondary",
                    width="stretch",
                    disabled=not bool(section.get("enabled", True)),
                ):
                    st.session_state[_navigation_secondary_state_key()] = secondary_key
                    actions = list(section.get("supported_tertiary_actions") or [])
                    st.session_state[_navigation_tertiary_state_key()] = _safe_text(
                        section.get("default_tertiary_action"),
                        (
                            _safe_text(actions[0].get("tertiary_key"), "")
                            if actions
                            else ""
                        ),
                    )
                    st.session_state[_navigation_prior_route_key()] = {
                        "page": _safe_text(
                            st.session_state.get("atlas_active_page"), ""
                        ),
                        "workspace": primary,
                        "mode": mode,
                    }
                    st.session_state["atlas_active_page"] = _safe_text(
                        section.get("route"),
                        _safe_text(
                            st.session_state.get("atlas_active_page"),
                            "Mission Control",
                        ),
                    )
                    st.rerun()

    with shell_cols[1]:
        section = next(
            (
                item
                for item in sections
                if _safe_text(item.get("secondary_key"), "")
                == _safe_text(
                    st.session_state.get(_navigation_secondary_state_key()), ""
                )
            ),
            sections[0],
        )
        actions = [
            item
            for item in list(section.get("supported_tertiary_actions") or [])
            if bool(item.get("visibility", True))
        ]
        if actions:
            action_cols = st.columns(max(1, min(6, len(actions))))
            for index, action in enumerate(actions):
                key = _safe_text(action.get("tertiary_key"), "")
                label = _safe_text(action.get("label"), key)
                requires_selection = _tertiary_action_requires_selection(
                    st,
                    action,
                    record,
                )
                if action_cols[index % len(action_cols)].button(
                    label,
                    key=f"atlas_tertiary_{primary}_{mode}_{_safe_text(section.get('secondary_key'), '')}_{key}",
                    type=(
                        "primary"
                        if key
                        == _safe_text(
                            st.session_state.get(_navigation_tertiary_state_key()),
                            "",
                        )
                        else "secondary"
                    ),
                    disabled=requires_selection
                    or not bool(action.get("enabled", True)),
                    width="stretch",
                ):
                    st.session_state[_navigation_tertiary_state_key()] = key
                    st.session_state[_navigation_prior_route_key()] = {
                        "page": _safe_text(
                            st.session_state.get("atlas_active_page"), ""
                        ),
                        "workspace": primary,
                        "mode": mode,
                    }
                    route = _safe_text(action.get("route"), "")
                    if route:
                        st.session_state["atlas_active_page"] = route
                    st.rerun()

            active_action = next(
                (
                    item
                    for item in actions
                    if _safe_text(item.get("tertiary_key"), "")
                    == _safe_text(
                        st.session_state.get(_navigation_tertiary_state_key()), ""
                    )
                ),
                actions[0],
            )
            if _tertiary_action_requires_selection(st, active_action, record):
                st.caption(
                    _safe_text(
                        active_action.get("empty_state_behavior"),
                        "Select a record in Browse to continue.",
                    )
                )
                fallback = _safe_text(
                    active_action.get("deterministic_fallback"), "browse"
                )
                if st.button(
                    "Open Browse",
                    key=(
                        f"atlas_tertiary_fallback_{primary}_{mode}_{_safe_text(section.get('secondary_key'), '')}_{fallback}"
                    ),
                    width="content",
                ):
                    st.session_state[_navigation_tertiary_state_key()] = fallback
                    st.rerun()


def _render_navigation_menu(
    st: Any,
    host: Any,
    menu_label: str,
    entries: list[tuple[str, str]],
    active_page: str,
) -> None:
    menu = host.popover(menu_label)
    menu.caption("Navigate to a workspace page.")
    for label, page in entries:
        is_future_disabled = page in DISABLED_LIFECYCLE_PAGES
        if menu.button(
            label,
            key=f"atlas_top_nav_{menu_label}_{label}_{page}",
            type="primary" if active_page == page else "secondary",
            disabled=is_future_disabled,
            width="stretch",
        ):
            _open_page(st, page)
        if is_future_disabled:
            menu.caption(f"{label} is reserved for future lifecycle scope.")


def _render_top_navigation(
    st: Any,
    nav_columns: list[Any],
    record: ProjectWorkspaceRecord | None = None,
) -> None:
    active_page = st.session_state.get("atlas_active_page", "Mission Control")
    nav_items = [
        ("Projects", "Projects"),
        ("Knowledge", "Knowledge"),
        ("Transactions", "Transactions"),
        ("Reports", "Reports"),
    ]

    for column, (label, page) in zip(nav_columns, nav_items):
        is_active = active_page == page
        if (
            label == "Projects"
            and record is not None
            and active_page != "Mission Control"
        ):
            is_active = True
        elif label == "Knowledge" and active_page in KNOWLEDGE_PAGES:
            is_active = True
        elif label == "Transactions" and active_page == "Transactions":
            is_active = True
        if column.button(
            label,
            key=f"atlas_header_nav_{label}",
            type="primary" if is_active else "secondary",
            width="content",
        ):
            _open_page(st, page)


def _render_header_menu(st: Any, host: Any) -> None:
    menu = host.popover("☰")
    if menu.button(
        "Settings",
        key="atlas_header_settings",
        type="secondary",
        width="stretch",
    ):
        _open_page(st, "Administration")


def _render_header(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    record: ProjectWorkspaceRecord | None,
    context: dict[str, Any] | None,
) -> None:
    current_page = st.session_state.get("atlas_active_page", "Mission Control")

    header_cols = st.columns([1.05, 3.2, 3.6, 0.55])
    if header_cols[0].button(
        "Atlas",
        key="atlas_header_nav_Atlas",
        width="content",
        type="primary" if current_page == "Mission Control" else "secondary",
    ):
        _open_page(st, "Mission Control")
    nav_cols = header_cols[1].columns([0.85, 1.0, 1.3, 0.85])
    _render_top_navigation(st, nav_cols, record)
    _render_global_search_control(st, header_cols[2])
    _render_header_menu(st, header_cols[3])

    if record is None or current_page == "Mission Control":
        st.session_state["atlas_active_project_name"] = ""
        return
    st.session_state["atlas_active_project_name"] = record.project.name


def _nav_buttons(
    st: Any,
    host: Any,
    mode: str,
    record: ProjectWorkspaceRecord | None,
) -> None:
    active_page = st.session_state.get("atlas_active_page", "Mission Control")
    nav_groups = (
        APPLICATION_NAV_GROUPS
        if active_page == "Mission Control"
        else _navigation_groups(record)
    )

    if record is not None and active_page != "Mission Control":
        host.markdown("### Active Project")
        host.caption("Project workspace")
        host.markdown("---")

    for group_name, entries in nav_groups:
        with host.expander(
            group_name,
            expanded=active_page in [item[1] for item in entries],
        ):
            for label, page in entries:
                is_future_disabled = page in DISABLED_LIFECYCLE_PAGES
                if host.button(
                    label,
                    key=f"atlas_nav_{mode}_{group_name}_{label}_{page}",
                    type="primary" if active_page == page else "secondary",
                    disabled=is_future_disabled,
                    width="stretch",
                ):
                    st.session_state["atlas_active_page"] = page
                    st.rerun()
                if is_future_disabled:
                    host.caption(f"{label} is reserved for future lifecycle scope.")


def _render_object_metadata_table(
    st: Any,
    title: str,
    rows: list[dict[str, Any]],
) -> None:
    st.markdown(f"### {title}")
    st.dataframe(rows, width="stretch", hide_index=True)


def _render_object_reference_sections(
    st: Any,
    *,
    record: ProjectWorkspaceRecord,
    graph: dict[str, Any],
    kind: str,
    selected: dict[str, Any],
    key_prefix: str,
) -> None:
    st.markdown("### References and Referenced By")
    references, referenced_by = _reference_groups_for_selection(
        record,
        graph,
        kind,
        selected,
    )
    reference_cols = st.columns(2)
    with reference_cols[0]:
        _render_reference_group(
            st,
            title="References",
            references=references,
            empty_message=f"This {_object_type_label(kind).lower()} has no outgoing references yet.",
            key_prefix=f"{key_prefix}_refs",
        )
    with reference_cols[1]:
        _render_reference_group(
            st,
            title="Referenced By",
            references=referenced_by,
            empty_message=f"No objects currently reference this {_object_type_label(kind).lower()}.",
            key_prefix=f"{key_prefix}_refby",
        )


def _object_recommended_actions(
    kind: str, data: dict[str, Any]
) -> list[dict[str, str]]:
    if kind == "equipment":
        return _equipment_recommended_actions(data)

    warnings = list(data.get("warnings") or [])
    has_links = any(
        list(data.get(field) or [])
        for field in [
            "referenced_equipment",
            "referenced_specifications",
            "referenced_drawings",
            "referenced_systems",
            "referenced_evidence",
        ]
    )

    actions: list[dict[str, str]] = []
    if warnings:
        actions.append(
            {
                "priority": "High",
                "action": "Review warnings and evidence",
                "destination": "Evidence",
                "reason": "Warnings indicate unresolved review context for this object.",
            }
        )
    if not has_links:
        actions.append(
            {
                "priority": "Medium",
                "action": "Validate cross-object references",
                "destination": "Relationships",
                "reason": "No connected objects were detected for this item.",
            }
        )
    if not actions:
        actions.append(
            {
                "priority": "Low",
                "action": "Continue review",
                "destination": "Relationships",
                "reason": "Object has linked context and no active warnings.",
            }
        )
    return actions


