def _render_knowledge_entity_import_export_controls(
    st: Any,
    product_service: CommercialProductService,
    *,
    entity_type: str,
    key_prefix: str,
) -> None:
    template = product_service.knowledge_entity_csv_template(entity_type=entity_type)
    export_filter = st.text_input(
        "Export Filter",
        key=f"{key_prefix}_export_filter",
        placeholder="optional contains filter",
    )
    csv_export = product_service.export_knowledge_entities_csv(
        entity_type=entity_type,
        include_inactive=True,
        query=export_filter,
    )
    json_export = product_service.export_knowledge_entities_json(
        entity_type=entity_type,
        include_inactive=True,
        query=export_filter,
    )

    export_cols = st.columns(3)
    export_cols[0].download_button(
        "Download CSV Template",
        data=template,
        file_name=f"{entity_type}_template.csv",
        mime="text/csv",
        key=f"{key_prefix}_template_download",
        width="stretch",
    )
    export_cols[1].download_button(
        "Export Filtered CSV",
        data=csv_export,
        file_name=f"{entity_type}_export.csv",
        mime="text/csv",
        key=f"{key_prefix}_csv_export",
        width="stretch",
    )
    export_cols[2].download_button(
        "Export JSON",
        data=json_export,
        file_name=f"{entity_type}_export.json",
        mime="application/json",
        key=f"{key_prefix}_json_export",
        width="stretch",
    )

    uploaded = st.file_uploader(
        f"Import {entity_type.title()} CSV",
        type=["csv"],
        key=f"{key_prefix}_import_file",
    )
    if uploaded is None:
        return

    file_bytes = uploaded.getvalue()
    preview = product_service.preview_knowledge_entity_import_csv(
        entity_type=entity_type,
        file_bytes=file_bytes,
    )
    st.caption(
        f"Preview: records={preview.get('record_count', 0)} accepted={preview.get('accepted_count', 0)} rejected={preview.get('rejected_count', 0)}"
    )
    st.dataframe(
        [
            {
                "Row": int(item.get("row_number") or 0),
                "Status": _safe_text(item.get("status"), ""),
                "Errors": " | ".join(list(item.get("errors") or [])),
                "Warnings": " | ".join(list(item.get("warnings") or [])),
            }
            for item in list(preview.get("preview_rows") or [])
        ],
        width="stretch",
        hide_index=True,
    )

    import_key = f"{key_prefix}_import_result"
    if st.button(
        "Import CSV (Partial Success)",
        key=f"{key_prefix}_import_apply",
        width="stretch",
    ):
        result = product_service.import_knowledge_entities_from_csv(
            entity_type=entity_type,
            file_bytes=file_bytes,
            allow_partial_success=True,
        )
        st.session_state[import_key] = result
        _save_commercial_product_state(st, product_service)
        st.success(
            f"Imported {int(result.get('imported_rows', 0) or 0)} rows with {int(result.get('rejected_rows', 0) or 0)} rejected rows."
        )
        st.rerun()

    result = dict(st.session_state.get(import_key) or {})
    if int(result.get("rejected_rows", 0) or 0) > 0:
        st.download_button(
            "Download Rejected Rows CSV",
            data=_safe_text(result.get("rejected_rows_csv"), ""),
            file_name=f"{entity_type}_rejected_rows.csv",
            mime="text/csv",
            key=f"{key_prefix}_rejected_export",
            width="stretch",
        )


def _build_object_reference(
    *,
    kind: str,
    data: dict[str, Any],
    project_id: str,
    project_name: str | None = None,
    route: str,
    relationship_count: int = 0,
    warning_count: int = 0,
) -> dict[str, Any]:
    status = _safe_text(
        data.get("completeness_status"),
        _safe_text(data.get("status"), _safe_text(data.get("current_status"), "n/a")),
    )
    confidence_value = data.get("confidence")
    confidence_text = (
        str(round(float(confidence_value), 2))
        if isinstance(confidence_value, (int, float))
        else _safe_text(confidence_value, "n/a")
    )
    source_refs = list(data.get("source_documents") or [])
    if not source_refs and kind == "evidence":
        source_refs = [_safe_text(data.get("source_file"), "")]
    identity_payload = _universal_identity_payload(
        kind=kind,
        data=data,
        route=route,
        project_id=project_id,
    )
    return {
        "object_id": _object_id_for_selection(kind, data),
        "object_type": _object_type_label(kind),
        "display_name": _object_display_name(kind, data),
        "secondary_label": _object_secondary_label(kind, data),
        "status": status,
        "confidence": confidence_text,
        "project_id": project_id,
        "project_name": _safe_text(project_name, project_id),
        "route": route,
        "source_refs": [item for item in source_refs if _safe_text(item, "")],
        "relationship_count": int(relationship_count),
        "warning_count": int(warning_count),
        "selection_kind": kind,
        "selection_data": dict(data),
        "universal_object_identity": identity_payload,
        "universal_object_id": _safe_text(
            identity_payload.get("universal_object_id"),
            "",
        ),
    }


def _track_recently_viewed(st: Any, reference: dict[str, Any]) -> None:
    object_id = _safe_text(reference.get("object_id"), "")
    object_type = _safe_text(reference.get("object_type"), "")
    if not object_id or not object_type:
        return
    existing = list(st.session_state.get("atlas_recently_viewed_objects") or [])
    filtered = [
        item
        for item in existing
        if not (
            _safe_text(item.get("object_id"), "") == object_id
            and _safe_text(item.get("object_type"), "") == object_type
        )
    ]
    entry = dict(reference)
    entry["last_viewed_at"] = _now_iso()
    filtered.insert(0, entry)
    st.session_state["atlas_recently_viewed_objects"] = filtered[:30]


def _working_set(st: Any) -> list[dict[str, Any]]:
    return list(st.session_state.get("atlas_pinned_objects") or [])


def _toggle_pin_reference(st: Any, reference: dict[str, Any], should_pin: bool) -> None:
    object_id = _safe_text(reference.get("object_id"), "")
    object_type = _safe_text(reference.get("object_type"), "")
    if not object_id or not object_type:
        return
    existing = list(st.session_state.get("atlas_pinned_objects") or [])
    filtered = [
        item
        for item in existing
        if not (
            _safe_text(item.get("object_id"), "") == object_id
            and _safe_text(item.get("object_type"), "") == object_type
        )
    ]
    if should_pin:
        filtered.insert(0, dict(reference))
    st.session_state["atlas_pinned_objects"] = filtered[:40]


def _move_working_set_item(
    st: Any,
    *,
    object_id: str,
    object_type: str,
    direction: int,
) -> None:
    items = _working_set(st)
    index = next(
        (
            i
            for i, item in enumerate(items)
            if _safe_text(item.get("object_id"), "") == object_id
            and _safe_text(item.get("object_type"), "") == object_type
        ),
        None,
    )
    if index is None:
        return
    target = index + direction
    if target < 0 or target >= len(items):
        return
    items[index], items[target] = items[target], items[index]
    st.session_state["atlas_pinned_objects"] = items


def _record_recent_search_query(st: Any, query: str) -> None:
    normalized = query.strip()
    if len(normalized) < 2:
        return
    existing = [
        str(item)
        for item in list(st.session_state.get("atlas_recent_search_queries") or [])
    ]
    deduped = [item for item in existing if item.lower() != normalized.lower()]
    deduped.insert(0, normalized)
    st.session_state["atlas_recent_search_queries"] = deduped[:12]


def _record_recent_search_open(st: Any, reference: dict[str, Any]) -> None:
    object_id = _safe_text(reference.get("object_id"), "")
    object_type = _safe_text(reference.get("object_type"), "")
    if not object_id or not object_type:
        return
    existing = list(st.session_state.get("atlas_recent_opened_results") or [])
    filtered = [
        item
        for item in existing
        if not (
            _safe_text(item.get("object_id"), "") == object_id
            and _safe_text(item.get("object_type"), "") == object_type
        )
    ]
    updated = dict(reference)
    updated["last_opened_at"] = _now_iso()
    filtered.insert(0, updated)
    st.session_state["atlas_recent_opened_results"] = filtered[:15]


def _is_reference_pinned(st: Any, reference: dict[str, Any]) -> bool:
    object_id = _safe_text(reference.get("object_id"), "")
    object_type = _safe_text(reference.get("object_type"), "")
    for item in list(st.session_state.get("atlas_pinned_objects") or []):
        if (
            _safe_text(item.get("object_id"), "") == object_id
            and _safe_text(item.get("object_type"), "") == object_type
        ):
            return True
    return False


def _set_context_selection(st: Any, kind: str, data: dict[str, Any]) -> None:
    st.session_state["atlas_context_selection"] = {"kind": kind, "data": data}
    _apply_context_selection_state(st, kind, data)


def _object_workspace_view_key() -> str:
    return "atlas_object_workspace_view"


def _ensure_object_workspace_view_state(st: Any) -> None:
    st.session_state.setdefault(_object_workspace_view_key(), "Summary")


def _set_object_workspace_view(st: Any, view: str) -> None:
    st.session_state[_object_workspace_view_key()] = _safe_text(view, "Summary")


def _current_selection(st: Any) -> tuple[str, dict[str, Any]]:
    selection = dict(st.session_state.get("atlas_context_selection") or {})
    return (
        _safe_text(selection.get("kind"), "project").lower(),
        dict(selection.get("data") or {}),
    )


def _selection_for_object_workspace(
    st: Any,
) -> tuple[str, dict[str, Any], str, str | None]:
    kind, data = _current_selection(st)
    if kind in OBJECT_WORKSPACE_SUPPORTED_KINDS:
        return (
            kind,
            data,
            _universal_object_adapter_key(kind),
            _safe_text(st.session_state.get("atlas_active_workspace_id"), ""),
        )

    if _safe_text(st.session_state.get("atlas_active_workspace_id"), ""):
        return (
            "project_record",
            {
                "workspace_id": _safe_text(
                    st.session_state.get("atlas_active_workspace_id"), ""
                ),
                "project_name": _safe_text(
                    st.session_state.get("atlas_active_project_name"),
                    "Project",
                ),
                "status": "active",
            },
            "project",
            _safe_text(st.session_state.get("atlas_active_workspace_id"), ""),
        )

    return (
        "project",
        {
            "project_id": "application",
            "project_name": "Atlas",
            "status": "indexed",
        },
        "project",
        None,
    )
    if kind not in {
        "equipment",
        "drawing",
        "specification",
        "system",
        "room",
        "rfi",
        "evidence",
        "manufacturer",
        "vendor",
        "customer",
        "price_list",
        "project_record",
        "master_product",
        "resolver_conflict",
        "resolved",
        "notebook_entry",
    }:
        return

    route = _selection_route(kind)
    if route == "Knowledge":
        _knowledge_navigation_defaults(st)
        _set_knowledge_navigation_selection(st, kind=kind)
    project_id = _safe_text(st.session_state.get("atlas_active_workspace_id"), "")
    warnings = list(data.get("warnings") or [])
    reference = _build_object_reference(
        kind=kind,
        data=data,
        project_id=project_id,
        project_name=_safe_text(
            st.session_state.get("atlas_active_project_name"), project_id
        ),
        route=route,
        relationship_count=0,
        warning_count=len(warnings),
    )
    _track_recently_viewed(st, reference)


def _render_object_card(
    st: Any,
    reference: dict[str, Any],
    *,
    key_prefix: str,
) -> None:
    status = _safe_text(reference.get("status"), "n/a")
    confidence = _safe_text(reference.get("confidence"), "n/a")
    relations = int(reference.get("relationship_count", 0) or 0)
    warnings = int(reference.get("warning_count", 0) or 0)
    secondary = _safe_text(reference.get("secondary_label"), "")
    st.markdown(
        "<div class='atlas-object-card'>"
        f"<div class='atlas-object-header'>{_safe_text(reference.get('object_type'), 'Object')}</div>"
        f"{_safe_text(reference.get('display_name'), 'Object')}"
        f"<br/><span class='atlas-muted'>{secondary}</span>"
        f"<br/><span class='atlas-muted'>Status: {status} · Confidence: {confidence} · Links: {relations} · Warnings: {warnings}</span>"
        "</div>",
        unsafe_allow_html=True,
    )
    cols = st.columns(2)
    if cols[0].button(
        f"Open {_safe_text(reference.get('display_name'), 'Object')}",
        key=f"{key_prefix}_open_{_safe_text(reference.get('object_type'), 'obj')}_{_safe_text(reference.get('object_id'), 'id')}",
        width="stretch",
    ):
        selection_kind = _safe_text(reference.get("selection_kind"), "project")
        target_page = (
            "Object Workspace"
            if selection_kind in OBJECT_WORKSPACE_SUPPORTED_KINDS
            else _safe_text(reference.get("route"), "Overview")
        )
        st.session_state["atlas_active_page"] = target_page
        _set_context_selection(
            st,
            selection_kind.lower().replace(" / ", "_"),
            dict(reference.get("selection_data") or {}),
        )
        if target_page == "Object Workspace":
            _set_object_workspace_view(st, "Summary")
        st.rerun()

    pinned = _is_reference_pinned(st, reference)
    if cols[1].button(
        "Remove" if pinned else "Add to Working Set",
        key=f"{key_prefix}_pin_{_safe_text(reference.get('object_type'), 'obj')}_{_safe_text(reference.get('object_id'), 'id')}",
        width="stretch",
    ):
        _toggle_pin_reference(st, reference, should_pin=not pinned)
        st.rerun()


def _render_object_header(
    st: Any,
    record: ProjectWorkspaceRecord,
    reference: dict[str, Any],
    *,
    description: str,
    recommended_action: str,
) -> None:
    st.markdown(f"#### {_safe_text(reference.get('display_name'), 'Object')}")
    st.caption(description)
    badges = [
        _safe_text(reference.get("object_type"), "Object"),
        _safe_text(reference.get("status"), "n/a").replace("_", " ").title(),
        f"Confidence {_safe_text(reference.get('confidence'), 'n/a')}",
        f"Project {_safe_text(record.project.name, 'Project')}",
    ]
    st.markdown(" ".join([f"`{badge}`" for badge in badges]))
    header_cols = st.columns([5.5, 2.25, 2.25])
    header_cols[0].caption(f"Recommended action: {recommended_action}")
    if header_cols[1].button(
        "Open Estimate Workspace",
        key=f"atlas_object_header_open_estimate_{_safe_text(reference.get('object_type'), 'obj')}_{_safe_text(reference.get('object_id'), 'id')}",
        width="stretch",
    ):
        st.session_state["atlas_active_page"] = "Estimate"
        st.rerun()
    pinned = _is_reference_pinned(st, reference)
    if header_cols[2].button(
        "Remove from Working Set" if pinned else "Add to Working Set",
        key=f"atlas_object_header_pin_{_safe_text(reference.get('object_type'), 'obj')}_{_safe_text(reference.get('object_id'), 'id')}",
        width="stretch",
    ):
        _toggle_pin_reference(st, reference, should_pin=not pinned)
        st.rerun()


def _object_workspace_authoritative_route(kind: str) -> str:
    mapping = {
        "customer": "Knowledge",
        "vendor": "Knowledge",
        "manufacturer": "Knowledge",
        "master_product": "Knowledge",
        "service": "Knowledge",
        "contact": "Knowledge",
        "location": "Knowledge",
        "project": "Overview",
        "project_record": "Overview",
        "drawing": "Drawings",
        "specification": "Specifications",
        "equipment": "Equipment",
        "commercial_document": "Transactions",
        "estimate": "Transactions",
        "proposal": "Transactions",
        "sales_order": "Transactions",
        "purchase_order": "Transactions",
        "request_for_quote": "Transactions",
        "vendor_quote": "Transactions",
        "receiving": "Transactions",
        "vendor_bill": "Transactions",
        "customer_invoice": "Transactions",
        "change_order": "Transactions",
    }
    return mapping.get(kind, "Overview")


def _object_workspace_supported_views(
    universal_object: Any,
    *,
    kind: str,
) -> list[str]:
    presentation = getattr(universal_object, "presentation", None)
    if presentation is None:
        return ["Summary", "Details", "Relationships"]
    supported = [
        _safe_text(item, "")
        for item in list(getattr(presentation, "supported_views", []) or [])
        if _safe_text(item, "")
    ]
    if kind in OBJECT_WORKSPACE_READ_ONLY_KINDS:
        supported = [item for item in supported if item.lower() != "documents"]
    display_order = [
        "summary",
        "lifecycle",
        "details",
        "relationships",
        "activity",
        "documents",
        "history",
    ]
    ordered = [
        item.title()
        for item in display_order
        if item in {entry.lower() for entry in supported}
    ]
    if not ordered:
        ordered = ["Summary", "Details", "Relationships"]
    return ordered


def _object_workspace_activity_rows(
    universal_object: Any,
    workspace_service: ProjectWorkspaceService,
    *,
    kind: str,
    data: dict[str, Any],
    record: ProjectWorkspaceRecord | None,
    product_service: CommercialProductService,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in list(getattr(universal_object, "activity", []) or []):
        item_payload = item.to_dict() if hasattr(item, "to_dict") else dict(item)
        rows.append(
            {
                "timestamp": _safe_text(item_payload.get("timestamp"), "n/a"),
                "activity": _safe_text(item_payload.get("activity_type"), "updated"),
                "actor": _safe_text(item_payload.get("actor"), "system"),
                "summary": _safe_text(item_payload.get("summary"), "Activity"),
                "source": _safe_text(item_payload.get("source"), "atlas"),
                "before": _safe_text(item_payload.get("before_state_ref"), ""),
                "after": _safe_text(item_payload.get("after_state_ref"), ""),
            }
        )

    if kind in _knowledge_selection_kinds():
        entity_id = _safe_text(data.get("entity_id"), "")
        if not entity_id:
            selected_id = _safe_text(_object_id_for_selection(kind, data), "")
            prefix = {
                "customer": "customer",
                "vendor": "vendor",
                "manufacturer": "manufacturer",
                "service": "service",
                "contact": "contact",
                "location": "location",
                "project": "project",
                "master_product": "product",
            }.get(kind, kind)
            if selected_id:
                entity_id = f"{prefix}:{selected_id}"
        try:
            audit_rows = product_service.list_knowledge_audit_events(
                entity_id=entity_id,
                limit=50,
            )
        except Exception:
            audit_rows = []
        for item in audit_rows:
            rows.append(
                {
                    "timestamp": _safe_text(item.get("timestamp"), "n/a"),
                    "activity": _safe_text(item.get("event_type"), "updated"),
                    "actor": "system",
                    "summary": _safe_text(item.get("entity_id"), "Knowledge Event"),
                    "source": "knowledge_audit",
                    "before": "",
                    "after": "",
                }
            )

    if kind in {"project", "project_record"} and record is not None:
        try:
            history_rows = workspace_service.list_history(record.workspace_id, limit=80)
        except Exception:
            history_rows = []
        for item in history_rows:
            item_payload = (
                dict(item.get("payload") or {})
                if isinstance(item.get("payload"), dict)
                else {}
            )
            rows.append(
                {
                    "timestamp": _safe_text(item.get("timestamp"), "n/a"),
                    "activity": _safe_text(item.get("event_type"), "event"),
                    "actor": _safe_text(
                        item_payload.get("actor"),
                        _safe_text(item.get("actor"), "system"),
                    ),
                    "summary": _safe_text(
                        item_payload.get("reason"),
                        _safe_text(item.get("event_type"), "project event")
                        .replace("_", " ")
                        .title(),
                    ),
                    "source": "project_history",
                    "before": _safe_text(
                        item_payload.get("source_stage"),
                        _safe_text(item_payload.get("source_status"), ""),
                    ),
                    "after": _safe_text(
                        item_payload.get("destination_stage"),
                        _safe_text(item_payload.get("destination_status"), ""),
                    ),
                }
            )

    rows.sort(key=lambda item: _safe_text(item.get("timestamp"), ""), reverse=True)
    return rows[:80]


def _object_workspace_relationship_rows(universal_object: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in list(getattr(universal_object, "relationships", []) or []):
        payload = item.to_dict() if hasattr(item, "to_dict") else dict(item)
        target = dict(payload.get("target_identity") or {})
        rows.append(
            {
                "relationship": _safe_text(
                    payload.get("relationship_type"), "related-to"
                ),
                "direction": _safe_text(payload.get("direction"), "outgoing"),
                "target": _safe_text(
                    target.get("canonical_display_name"),
                    _safe_text(target.get("object_id"), "n/a"),
                ),
                "target_type": _safe_text(target.get("object_type"), "object"),
                "status": _safe_text(payload.get("status"), ""),
                "confidence": _safe_text(payload.get("confidence"), ""),
                "provenance": _safe_text(
                    dict(payload.get("provenance") or {}).get("source"), ""
                ),
            }
        )
    return rows


def _permission_scope_for_object(universal_object: Any, kind: str) -> str:
    identity = getattr(universal_object, "identity", None)
    owning_workspace = _safe_text(
        getattr(identity, "owning_workspace", None), "Projects"
    ).lower()
    if owning_workspace == "transactions" or kind in {
        "commercial_document",
        "estimate",
        "proposal",
        "sales_order",
        "purchase_order",
        "request_for_quote",
        "vendor_quote",
        "receiving",
        "vendor_bill",
        "customer_invoice",
        "change_order",
    }:
        return "transactions"
    if owning_workspace == "knowledge" or kind in {
        "customer",
        "vendor",
        "manufacturer",
        "service",
        "contact",
        "location",
        "master_product",
    }:
        return "knowledge"
    return "projects"


def _authorized_object_actions(
    st: Any,
    *,
    kind: str,
    universal_object: Any,
) -> list[dict[str, Any]]:
    transactions_state = _transactions_workspace_state(st)
    tenant_id = _safe_text(st.session_state.get(_tenant_scope_key()), "local")
    organization_id = _safe_text(transactions_state.get("organization_id"), "atlas")
    principal_id = _safe_text(
        st.session_state.get("atlas_settings_user_id"), "local-user"
    )
    project_id = (
        _safe_text(st.session_state.get("atlas_active_workspace_id"), "") or None
    )
    scope = _permission_scope_for_object(universal_object, kind)
    permissions_service = _permissions_workspace_service(st)

    actions: list[dict[str, Any]] = []
    for item in list(getattr(universal_object, "actions", []) or []):
        payload = item.to_dict() if hasattr(item, "to_dict") else dict(item)
        access = permissions_service.action_access(
            tenant_id=tenant_id,
            organization_id=organization_id,
            principal_id=principal_id,
            permission_hook=_safe_text(payload.get("permission_hook"), "") or None,
            action_key=_safe_text(payload.get("action_key"), ""),
            workspace_scope=scope,
            project_id=project_id,
        )
        if not access.visible:
            continue
        payload["enabled"] = bool(payload.get("enabled", True)) and access.enabled
        if not payload["enabled"] and not _safe_text(
            payload.get("disabled_reason"), ""
        ):
            payload["disabled_reason"] = _safe_text(access.reason, "Action unavailable")
        payload["permission_key"] = access.permission_key
        payload["access_diagnostics"] = access.decision.to_dict()
        actions.append(payload)
    return actions


def _attachment_access_decision(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    *,
    universal_object: Any,
    kind: str,
    action_key: str,
    project_id: str | None,
) -> tuple[Any, str]:
    transactions_state = _transactions_workspace_state(st)
    tenant_id = _safe_text(st.session_state.get(_tenant_scope_key()), "local")
    organization_id = _safe_text(transactions_state.get("organization_id"), "atlas")
    principal_id = _safe_text(
        st.session_state.get("atlas_settings_user_id"), "local-user"
    )
    permissions_service = _permissions_workspace_service(st)
    scope = _permission_scope_for_object(universal_object, kind)
    access = permissions_service.action_access(
        tenant_id=tenant_id,
        organization_id=organization_id,
        principal_id=principal_id,
        permission_hook=None,
        action_key=action_key,
        workspace_scope=scope,
        project_id=project_id,
    )
    decision = workspace_service.manager.attachment_service.decision_from_permissions(
        allowed=bool(access.enabled),
        permission_key=_safe_text(access.permission_key, f"{scope}.view"),
        reason=_safe_text(access.reason, "") or None,
        decision_code="allowed" if bool(access.enabled) else "denied",
        surface=str(getattr(access.decision, "surface", "")) or None,
    )
    return decision, _safe_text(access.reason, "")


def _render_object_workspace_actions(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    *,
    kind: str,
    data: dict[str, Any],
    universal_object: Any,
    record: ProjectWorkspaceRecord | None,
) -> None:
    st.markdown("### Primary Actions")
    actions = _authorized_object_actions(
        st,
        kind=kind,
        universal_object=universal_object,
    )
    if not actions:
        st.caption("No actions available.")
        return

    cols = st.columns(min(4, max(1, len(actions))))
    for index, action in enumerate(actions[:8]):
        label = _safe_text(
            action.get("label"), _safe_text(action.get("action_key"), "Action")
        )
        enabled = bool(action.get("enabled", True))
        clicked = cols[index % len(cols)].button(
            label,
            key=f"atlas_object_workspace_action_{_safe_text(action.get('action_key'), 'action')}_{index}",
            width="stretch",
            disabled=not enabled,
        )
        if not enabled:
            reason = _safe_text(action.get("disabled_reason"), "Action unavailable")
            cols[index % len(cols)].caption(reason)
            continue
        if not clicked:
            continue

        action_key = _safe_text(action.get("action_key"), "")
        if action_key == "return_to_origin":
            entry = dict(st.session_state.get(_return_context_key()) or {})
            if entry and _return_context_is_compatible(st, workspace_service, entry):
                _restore_context_entry(st, workspace_service, entry)
            return
        if action_key == "view_activity":
            _set_object_workspace_view(st, "Activity")
            st.rerun()
            return
        if action_key == "view_documents":
            _set_object_workspace_view(st, "Documents")
            st.rerun()
            return
        if action_key == "open":
            route = _object_workspace_authoritative_route(kind)
            st.session_state["atlas_active_page"] = route
            st.rerun()
            return
        if action_key == "archive":
            try:
                if kind in {"project", "project_record"} and record is not None:
                    workspace_service.archive_project(
                        record.workspace_id, archived=True
                    )
                else:
                    selected_id = _safe_text(_object_id_for_selection(kind, data), "")
                    prefix = {
                        "master_product": "product",
                        "customer": "customer",
                        "vendor": "vendor",
                        "manufacturer": "manufacturer",
                        "service": "service",
                        "contact": "contact",
                        "location": "location",
                        "project": "project",
                    }.get(kind, kind)
                    entity_id = (
                        _safe_text(data.get("entity_id"), "")
                        or f"{prefix}:{selected_id}"
                    )
                    service = _commercial_product_service(st)
                    service.set_knowledge_entity_active(
                        entity_id=entity_id, active=False
                    )
                    _save_commercial_product_state(st, service)
                st.success("Object archived.")
            except Exception as exc:
                st.error(f"Unable to archive object: {exc}")
            return
        if action_key == "restore":
            try:
                if kind in {"project", "project_record"} and record is not None:
                    workspace_service.archive_project(
                        record.workspace_id, archived=False
                    )
                else:
                    selected_id = _safe_text(_object_id_for_selection(kind, data), "")
                    prefix = {
                        "master_product": "product",
                        "customer": "customer",
                        "vendor": "vendor",
                        "manufacturer": "manufacturer",
                        "service": "service",
                        "contact": "contact",
                        "location": "location",
                        "project": "project",
                    }.get(kind, kind)
                    entity_id = (
                        _safe_text(data.get("entity_id"), "")
                        or f"{prefix}:{selected_id}"
                    )
                    service = _commercial_product_service(st)
                    service.set_knowledge_entity_active(
                        entity_id=entity_id, active=True
                    )
                    _save_commercial_product_state(st, service)
                st.success("Object restored.")
            except Exception as exc:
                st.error(f"Unable to restore object: {exc}")
            return
        if action_key == "export":
            st.download_button(
                "Download Object JSON",
                data=json.dumps(universal_object.to_dict(), indent=2, sort_keys=True),
                file_name=f"{_safe_text(getattr(universal_object.identity, 'object_type', 'object'), 'object')}_{_safe_text(getattr(universal_object.identity, 'object_id', 'record'), 'record')}.json",
                mime="application/json",
                width="stretch",
            )
            return
        if action_key == "edit":
            route = _object_workspace_authoritative_route(kind)
            st.session_state["atlas_active_page"] = route
            st.info("Use the authoritative workflow controls on the destination page.")
            st.rerun()


def _render_universal_object_workspace_page(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    record: ProjectWorkspaceRecord | None,
    context: dict[str, Any] | None,
) -> None:
    product_service = _commercial_product_service(st)
    _ensure_object_workspace_view_state(st)
    kind, data, adapter_key, selected_project_id = _selection_for_object_workspace(st)
    try:
        payload = dict(data)
        if kind in {"project", "project_record"} and record is not None:
            payload = {
                **record.metadata,
                **payload,
                "workspace_id": record.workspace_id,
                "project_id": record.project.project_id,
                "project_name": record.project.name,
                "client_project_number": _client_project_number(record),
                "internal_project_number": _internal_project_number(record),
                "status": _safe_text(
                    record.metadata.get("status"), record.project.status.value
                ),
                "lifecycle_stage": _safe_text(
                    record.metadata.get("lifecycle_stage"), _project_stage(record)
                ),
                "lifecycle_plan": dict(record.metadata.get("lifecycle_plan") or {}),
            }
        universal_object = _universal_object_registry().adapt(
            adapter_key,
            payload,
            tenant_id=_safe_text(st.session_state.get(_tenant_scope_key()), "local"),
            owning_workspace=(
                "Knowledge" if kind in _knowledge_selection_kinds() else "Projects"
            ),
            owning_project_id=selected_project_id or None,
        )
    except Exception:
        _render_guided_empty_state(
            st,
            why_empty="Selected object cannot be resolved through the Universal Object registry.",
            action_to_populate="Open a supported object from search, Working Set, or Knowledge/Project object lists.",
            next_location="Use supported object selections: Customer, Vendor, Manufacturer, Product, Service, Contact, Location, Project, Drawing, Specification, Equipment.",
        )
        return

    identity = universal_object.identity
    metadata = universal_object.metadata.to_dict()
    presentation = (
        universal_object.presentation.to_dict()
        if universal_object.presentation is not None
        else {}
    )
    _render_page_header(st, "Object Workspace", "")

    entry = dict(st.session_state.get(_return_context_key()) or {})
    if entry:
        origin = " / ".join(
            [
                _safe_text(entry.get("source_workspace"), "Atlas"),
                _safe_text(entry.get("source_route"), ""),
            ]
        ).strip(" /")
        banner_cols = st.columns([4.5, 1.5])
        banner_cols[0].caption(f"Opened from {origin}")
        if banner_cols[1].button(
            _return_context_label(entry),
            key="atlas_object_workspace_return",
            width="stretch",
        ):
            _restore_context_entry(st, workspace_service, entry)
            return

    st.markdown("### Object Identity")
    identity_rows = [
        {
            "Name": identity.canonical_display_name,
            "Type": _object_type_label(_safe_text(identity.object_type, kind)),
            "Identifier": _safe_text(identity.secondary_identifier, identity.object_id),
            "Status": _safe_text(identity.status, "n/a"),
            "Lifecycle": _safe_text(identity.lifecycle_state, "n/a"),
            "Workspace": _safe_text(identity.owning_workspace, "n/a"),
            "Project": _safe_text(identity.owning_project_id, "application"),
            "Tags": ", ".join(list(metadata.get("tags") or [])) or "n/a",
            "Created": _safe_text(identity.created_at, "n/a"),
            "Updated": _safe_text(identity.updated_at, "n/a"),
        }
    ]
    st.dataframe(identity_rows, width="stretch", hide_index=True)

    _render_object_workspace_actions(
        st,
        workspace_service,
        kind=kind,
        data=data,
        universal_object=universal_object,
        record=record,
    )

    supported_views = _object_workspace_supported_views(universal_object, kind=kind)
    current_view = _safe_text(
        st.session_state.get(_object_workspace_view_key()), "Summary"
    )
    if current_view not in supported_views:
        current_view = supported_views[0]
        _set_object_workspace_view(st, current_view)
    selected_view = st.radio(
        "Object View",
        options=supported_views,
        horizontal=True,
        key="atlas_object_workspace_view_selector",
        index=supported_views.index(current_view),
    )
    _set_object_workspace_view(st, selected_view)

    if selected_view == "Summary":
        st.markdown("### Summary")
        relationships = _object_workspace_relationship_rows(universal_object)
        st.dataframe(
            [
                {
                    "Primary Label": _safe_text(
                        presentation.get("primary_label"),
                        identity.canonical_display_name,
                    ),
                    "Secondary Label": _safe_text(
                        presentation.get("secondary_label"),
                        _object_secondary_label(kind, data),
                    )
                    or "n/a",
                    "Warnings": len(list(metadata.get("warnings") or [])),
                    "Related Objects": len(relationships),
                    "Recommended Next Action": (
                        "Review relationship links"
                        if relationships
                        else "Review details and provenance"
                    ),
                }
            ],
            width="stretch",
            hide_index=True,
        )
        if metadata.get("warnings"):
            st.markdown("#### Warnings")
            st.dataframe(
                [
                    {"warning": _safe_text(item, "")}
                    for item in list(metadata.get("warnings") or [])
                ],
                width="stretch",
                hide_index=True,
            )

    elif selected_view == "Details":
        st.markdown("### Details")
        detail_rows = [
            {
                "Field": key.replace("_", " ").title(),
                "Value": (
                    _safe_text(value, "n/a")
                    if not isinstance(value, (list, dict))
                    else json.dumps(value, sort_keys=True)
                ),
            }
            for key, value in dict(data).items()
        ]
        _render_data_table(st, detail_rows[:60])

    elif selected_view == "Relationships":
        st.markdown("### Relationships")
        relationship_rows = _object_workspace_relationship_rows(universal_object)
        if relationship_rows:
            _render_data_table(st, relationship_rows)
        else:
            _render_guided_empty_state(
                st,
                why_empty="No deterministic relationships are currently available for this object.",
                action_to_populate="Run existing review/import workflows that provide relationship evidence.",
                next_location="Use authoritative project and knowledge workflows to build linked evidence.",
            )

    elif selected_view == "Lifecycle":
        st.markdown("### Lifecycle Dashboard")
        lifecycle_plan = (
            workspace_service.lifecycle_plan_for_record(record)
            if kind in {"project", "project_record"} and record is not None
            else _lifecycle_plan_from_universal_object(universal_object)
        )
        if lifecycle_plan is None:
            _render_guided_empty_state(
                st,
                why_empty="No lifecycle plan is available for this project object.",
                action_to_populate="Open a project with persisted lifecycle state or load a compatibility-backed project record.",
                next_location="Use Project Workspace or Project search results.",
            )
        else:
            selected_stage_key = st.selectbox(
                "Lifecycle Stage",
                options=[item.stage_key for item in lifecycle_plan.stage_states],
                index=next(
                    (
                        index
                        for index, item in enumerate(lifecycle_plan.stage_states)
                        if item.stage_key == lifecycle_plan.current_stage_key
                    ),
                    0,
                ),
                format_func=_lifecycle_stage_label,
                key="atlas_object_workspace_lifecycle_stage",
            )
            selected_stage = (
                lifecycle_plan.stage(selected_stage_key) or lifecycle_plan.current_stage
            )
            stage_definition = _AV_LIFECYCLE_ENGINE.stage_definition(
                selected_stage.stage_key
            )
            completed_stages, blocked_stages, upcoming_stages = (
                _project_lifecycle_dashboard_rows(lifecycle_plan)
            )
            transitions = (
                workspace_service.available_project_lifecycle_transitions(
                    record.workspace_id
                )
                if kind in {"project", "project_record"} and record is not None
                else [
                    {
                        "to_stage_key": item.state,
                        "label": _safe_text(item.reason, item.state),
                    }
                    for item in list(
                        getattr(universal_object.lifecycle, "allowed_transitions", [])
                        or []
                    )
                ]
            )
            readiness = selected_stage.readiness or lifecycle_plan.readiness
            st.markdown(
                _render_lifecycle_timeline_html(
                    lifecycle_plan,
                    selected_stage_key=selected_stage.stage_key,
                ),
                unsafe_allow_html=True,
            )

            summary_cols = st.columns(4)
            summary_cols[0].markdown(
                render_metric_card_html(
                    "Current Stage",
                    _lifecycle_stage_label(lifecycle_plan.current_stage_key),
                ),
                unsafe_allow_html=True,
            )
            summary_cols[1].markdown(
                render_metric_card_html(
                    "Stage Status",
                    _lifecycle_status_label(lifecycle_plan.current_stage_status),
                ),
                unsafe_allow_html=True,
            )
            summary_cols[2].markdown(
                render_metric_card_html(
                    "Responsible Role",
                    _safe_text(
                        selected_stage.owner_role,
                        _safe_text(lifecycle_plan.current_owner_role, "unassigned"),
                    ).title(),
                ),
                unsafe_allow_html=True,
            )
            summary_cols[3].markdown(
                render_metric_card_html(
                    "Next Action",
                    _safe_text(
                        getattr(readiness, "recommended_next_action", None),
                        _safe_text(stage_definition.summary_action, "n/a"),
                    ),
                ),
                unsafe_allow_html=True,
            )

            st.dataframe(
                [
                    {
                        "Completed Stages": ", ".join(completed_stages) or "None",
                        "Blocked Stages": ", ".join(blocked_stages) or "None",
                        "Upcoming Stages": ", ".join(upcoming_stages[:6]) or "None",
                        "Available Transitions": ", ".join(
                            _lifecycle_stage_label(
                                _safe_text(item.get("to_stage_key"), "")
                            )
                            for item in transitions
                        )
                        or "None",
                    }
                ],
                width="stretch",
                hide_index=True,
            )

            st.markdown(
                render_notice_panel_html(
                    _lifecycle_stage_label(selected_stage.stage_key),
                    _lifecycle_stage_description(stage_definition, selected_stage),
                ),
                unsafe_allow_html=True,
            )

            if readiness is not None:
                st.markdown(
                    "".join(
                        [
                            render_status_badge_html(
                                f"Ready: {'Yes' if readiness.ready else 'No'}",
                                "success" if readiness.ready else "neutral",
                            ),
                            render_status_badge_html(
                                f"Needs Review: {'Yes' if readiness.needs_review else 'No'}",
                                "warning" if readiness.needs_review else "neutral",
                            ),
                            render_status_badge_html(
                                f"Blocked: {'Yes' if readiness.blocked else 'No'}",
                                "danger" if readiness.blocked else "neutral",
                            ),
                        ]
                    ),
                    unsafe_allow_html=True,
                )

            with st.expander("Readiness Diagnostics", expanded=False):
                diagnostics_rows = [
                    {
                        "Severity": _safe_text(item.severity, "info").title(),
                        "Code": _safe_text(item.code, "n/a"),
                        "Message": _safe_text(item.message, "n/a"),
                    }
                    for item in list(getattr(readiness, "diagnostics", []) or [])
                ]
                if diagnostics_rows:
                    _render_data_table(st, diagnostics_rows)
                else:
                    st.caption("No readiness diagnostics for the selected stage.")

            with st.expander("Transition Requirements", expanded=False):
                requirement_rows = [
                    {
                        "Category": _safe_text(item.category, "n/a")
                        .replace("_", " ")
                        .title(),
                        "Label": _safe_text(item.label, "n/a"),
                        "Required": "Yes" if item.required else "No",
                        "Satisfied": "Yes" if item.satisfied else "No",
                        "Details": _safe_text(item.details, ""),
                    }
                    for item in list(selected_stage.requirements or [])
                ]
                if requirement_rows:
                    _render_data_table(st, requirement_rows)
                else:
                    st.caption(
                        "No deterministic transition requirements captured for this stage."
                    )

            with st.expander("Transition History", expanded=False):
                history_rows = _lifecycle_stage_history_rows(
                    lifecycle_plan,
                    selected_stage.stage_key,
                )
                if history_rows:
                    _render_data_table(st, history_rows)
                else:
                    st.caption("No lifecycle events reference the selected stage yet.")

            with st.expander("Related Project Objects", expanded=False):
                related_objects = _lifecycle_stage_related_objects(
                    selected_stage, readiness
                )
                if related_objects:
                    _render_data_table(
                        st, [{"Object": item} for item in related_objects]
                    )
                else:
                    st.caption(
                        "No deterministic related project objects are available for this stage."
                    )

    elif selected_view == "Activity":
        st.markdown("### Activity")
        activity_rows = _object_workspace_activity_rows(
            universal_object,
            workspace_service,
            kind=kind,
            data=data,
            record=record,
            product_service=product_service,
        )
        if activity_rows:
            _render_data_table(st, activity_rows)
        else:
            _render_guided_empty_state(
                st,
                why_empty="No activity events are available for this object.",
                action_to_populate="Use existing update/import/archive workflows to generate auditable activity.",
                next_location="Return to authoritative workflow pages for this object.",
            )

    elif selected_view == "Documents":
        st.markdown("### Documents")
        transactions_state = _transactions_workspace_state(st)
        tenant_id = _safe_text(st.session_state.get(_tenant_scope_key()), "local")
        organization_id = _safe_text(transactions_state.get("organization_id"), "atlas")
        object_type = _safe_text(getattr(identity, "object_type", None), kind)
        object_id = _safe_text(
            getattr(identity, "object_id", None),
            _object_id_for_selection(kind, data),
        )
        scoped_project_id = record.workspace_id if record is not None else None

        attachment_rows: list[dict[str, Any]] = []
        if object_id:
            try:
                attachment_rows = workspace_service.list_object_attachments(
                    tenant_id=tenant_id,
                    organization_id=organization_id,
                    object_type=object_type,
                    object_id=object_id,
                    include_archived=True,
                    limit=200,
                )
            except Exception as exc:
                st.warning(f"Unable to load unified attachments: {exc}")

        if attachment_rows:
            table_rows = [
                {
                    "Attachment ID": _safe_text(item.get("attachment_id"), "n/a"),
                    "Filename": _safe_text(item.get("filename"), "n/a"),
                    "Type": _safe_text(item.get("mime_type"), "n/a"),
                    "Status": _safe_text(item.get("status"), "active"),
                    "Version": int(item.get("version_number", 1) or 1),
                    "Uploaded": _safe_text(item.get("uploaded_at"), "n/a"),
                }
                for item in attachment_rows
            ]
            _render_data_table(st, table_rows[:120])

            selected_label_map: dict[str, dict[str, Any]] = {}
            labels: list[str] = []
            for item in attachment_rows:
                label = (
                    f"{_safe_text(item.get('filename'), 'attachment')} "
                    f"[{_safe_text(item.get('attachment_id'), '')[:16]}]"
                )
                selected_label_map[label] = dict(item)
                labels.append(label)
            selected_label = st.selectbox(
                "Attachment Actions",
                options=labels,
                key="atlas_object_workspace_documents_attachment_selector",
            )
            selected_attachment = dict(selected_label_map.get(selected_label) or {})
            selected_attachment_id = _safe_text(
                selected_attachment.get("attachment_id"), ""
            )
            selected_link_id = _safe_text(selected_attachment.get("link_id"), "")
            selected_status = _safe_text(selected_attachment.get("status"), "active")

            download_payload_key = "atlas_object_workspace_attachment_download_payload"
            action_cols = st.columns(4)
            if action_cols[0].button(
                "Open / Download",
                key=f"atlas_attachment_open_{selected_attachment_id}",
                width="stretch",
                disabled=not bool(selected_attachment_id),
            ):
                decision, reason = _attachment_access_decision(
                    st,
                    workspace_service,
                    universal_object=universal_object,
                    kind=kind,
                    action_key="view_documents",
                    project_id=scoped_project_id,
                )
                if not decision.allowed:
                    st.warning(
                        reason or "You do not have permission to download attachments."
                    )
                elif selected_attachment_id:
                    try:
                        payload = workspace_service.read_object_attachment(
                            tenant_id=tenant_id,
                            organization_id=organization_id,
                            attachment_id=selected_attachment_id,
                            actor_id=_safe_text(
                                st.session_state.get("atlas_settings_user_id"),
                                "atlas-ui",
                            ),
                            access_decision=decision,
                            project_id=scoped_project_id,
                        )
                        st.session_state[download_payload_key] = payload
                        st.success("Attachment is ready for download.")
                    except Exception as exc:
                        st.error(f"Unable to open attachment: {exc}")

            archive_label = "Restore" if selected_status == "archived" else "Archive"
            if action_cols[1].button(
                archive_label,
                key=f"atlas_attachment_archive_{selected_attachment_id}",
                width="stretch",
                disabled=not bool(selected_attachment_id),
            ):
                decision, reason = _attachment_access_decision(
                    st,
                    workspace_service,
                    universal_object=universal_object,
                    kind=kind,
                    action_key=(
                        "archive" if selected_status != "archived" else "restore"
                    ),
                    project_id=scoped_project_id,
                )
                if not decision.allowed:
                    st.warning(
                        reason or "You do not have permission for archive actions."
                    )
                else:
                    try:
                        if selected_status == "archived":
                            workspace_service.restore_object_attachment(
                                tenant_id=tenant_id,
                                organization_id=organization_id,
                                attachment_id=selected_attachment_id,
                                actor_id=_safe_text(
                                    st.session_state.get("atlas_settings_user_id"),
                                    "atlas-ui",
                                ),
                                access_decision=decision,
                                project_id=scoped_project_id,
                            )
                            st.success("Attachment restored.")
                        else:
                            workspace_service.archive_object_attachment(
                                tenant_id=tenant_id,
                                organization_id=organization_id,
                                attachment_id=selected_attachment_id,
                                actor_id=_safe_text(
                                    st.session_state.get("atlas_settings_user_id"),
                                    "atlas-ui",
                                ),
                                access_decision=decision,
                                project_id=scoped_project_id,
                            )
                            st.success("Attachment archived.")
                        st.rerun()
                    except Exception as exc:
                        st.error(f"Unable to update attachment status: {exc}")

            if action_cols[2].button(
                "Unlink",
                key=f"atlas_attachment_unlink_{selected_link_id}",
                width="stretch",
                disabled=not bool(selected_link_id),
            ):
                decision, reason = _attachment_access_decision(
                    st,
                    workspace_service,
                    universal_object=universal_object,
                    kind=kind,
                    action_key="edit",
                    project_id=scoped_project_id,
                )
                if not decision.allowed:
                    st.warning(
                        reason or "You do not have permission to unlink attachments."
                    )
                else:
                    try:
                        workspace_service.unlink_object_attachment(
                            tenant_id=tenant_id,
                            organization_id=organization_id,
                            link_id=selected_link_id,
                            actor_id=_safe_text(
                                st.session_state.get("atlas_settings_user_id"),
                                "atlas-ui",
                            ),
                            access_decision=decision,
                            project_id=scoped_project_id,
                        )
                        st.success("Attachment unlinked from object.")
                        st.rerun()
                    except Exception as exc:
                        st.error(f"Unable to unlink attachment: {exc}")

            prepared_payload = dict(st.session_state.get(download_payload_key) or {})
            if (
                _safe_text(prepared_payload.get("attachment_id"), "")
                == selected_attachment_id
            ):
                action_cols[3].download_button(
                    "Download File",
                    data=prepared_payload.get("data") or b"",
                    file_name=_safe_text(
                        prepared_payload.get("filename"), "attachment.bin"
                    ),
                    mime=_safe_text(
                        prepared_payload.get("mime_type"), "application/octet-stream"
                    ),
                    key=f"atlas_attachment_download_{selected_attachment_id}",
                    width="stretch",
                )

        source_refs = list(metadata.get("source_references") or [])
        if kind in OBJECT_WORKSPACE_READ_ONLY_KINDS:
            source_refs.extend(
                [
                    _safe_text(data.get("source_file"), ""),
                    _safe_text(data.get("title"), ""),
                ]
            )
        source_refs = [item for item in source_refs if _safe_text(item, "")]
        if source_refs:
            st.markdown("#### Legacy Source References")
            _render_data_table(st, [{"document": item} for item in source_refs[:80]])
        elif not attachment_rows:
            _render_guided_empty_state(
                st,
                why_empty="No document links are available for this object.",
                action_to_populate="Open the authoritative workspace to inspect document sources.",
                next_location="Use Drawings, Specifications, Equipment, or Documents workspace pages.",
            )

    else:
        st.markdown("### History")
        if kind in {"project", "project_record"} and record is not None:
            history_rows = workspace_service.list_history(
                record.workspace_id, limit=100
            )
            if history_rows:
                _render_data_table(st, history_rows)
            else:
                _render_guided_empty_state(
                    st,
                    why_empty="No project history events were found.",
                    action_to_populate="Perform project operations to generate history events.",
                    next_location="Use project workflows and retry history view.",
                )
        else:
            _render_guided_empty_state(
                st,
                why_empty="History is not available for this object type in W-03.",
                action_to_populate="Use Activity view for current auditable events.",
                next_location="Future sprint will expand object history support.",
            )

    st.markdown("### Provenance")
    _render_data_table(
        st,
        [
            {
                "Source Authority": _safe_text(identity.source_authority, "atlas"),
                "Universal Object ID": _safe_text(identity.universal_object_id, "n/a"),
                "Owning Workspace": _safe_text(identity.owning_workspace, "n/a"),
                "Owning Project": _safe_text(identity.owning_project_id, "application"),
                "Schema Version": _safe_text(identity.schema_version, "n/a"),
            }
        ],
    )

    authoritative_route = _object_workspace_authoritative_route(kind)
    if kind in OBJECT_WORKSPACE_READ_ONLY_KINDS:
        st.caption("Read-only validation mode for this engineering object type.")
    if st.button(
        f"Open Authoritative View ({authoritative_route})",
        key="atlas_object_workspace_open_authoritative",
        width="stretch",
    ):
        st.session_state["atlas_active_page"] = authoritative_route
        st.rerun()


def _open_search_reference(
    st: Any,
    workspace_service: ProjectWorkspaceService,
    reference: dict[str, Any],
) -> None:
    route = _safe_text(reference.get("route"), "Overview")
    selection_kind = _safe_text(reference.get("selection_kind"), "project")
    selection_data = dict(reference.get("selection_data") or {})
    _record_return_context(
        st,
        source_label=_safe_text(
            reference.get("display_name"),
            _safe_text(reference.get("route"), "Object"),
        ),
    )

    if selection_kind == "project_record":
        workspace_id = _safe_text(
            selection_data.get("workspace_id"),
            _safe_text(reference.get("object_id"), ""),
        )
        if workspace_id:
            records = {
                item.workspace_id: item
                for item in workspace_service.list_workspaces(
                    include_archived=True,
                    limit=1000,
                )
            }
            selected_record = records.get(workspace_id)
            if selected_record is not None:
                _record_recent_search_open(st, reference)
                _open_project_record(st, selected_record, workspace_service)
                return

    if selection_kind in OBJECT_WORKSPACE_SUPPORTED_KINDS:
        st.session_state["atlas_active_page"] = "Object Workspace"
        _set_context_selection(st, selection_kind, selection_data)
        if selection_kind in _knowledge_selection_kinds() and selection_kind not in {
            "project",
            "project_record",
        }:
            _knowledge_navigation_defaults(st)
            _set_knowledge_navigation_selection(st, kind=selection_kind)
            st.session_state[_navigation_primary_state_key()] = "Knowledge"
            st.session_state[_navigation_mode_state_key()] = "application"
            st.session_state[_navigation_secondary_state_key()] = _safe_text(
                _secondary_key_for_page("Knowledge", "application", "Knowledge"),
                "overview",
            )
            st.session_state[_navigation_tertiary_state_key()] = "browse"
        elif selection_kind in {"project", "project_record"}:
            st.session_state[_navigation_primary_state_key()] = "Projects"
            st.session_state[_navigation_mode_state_key()] = "active"
            st.session_state[_navigation_secondary_state_key()] = "overview"
            st.session_state[_navigation_tertiary_state_key()] = "summary"
        elif selection_kind in _transaction_selection_kinds():
            st.session_state[_navigation_primary_state_key()] = "Transactions"
            st.session_state[_navigation_mode_state_key()] = "application"
            st.session_state[_navigation_secondary_state_key()] = next(
                (
                    key
                    for key, doc_type in TRANSACTION_SECONDARY_TO_DOCUMENT_TYPE.items()
                    if TRANSACTION_TYPE_TO_KIND.get(doc_type) == selection_kind
                ),
                "overview",
            )
            st.session_state[_navigation_tertiary_state_key()] = "browse"
        else:
            st.session_state[_navigation_primary_state_key()] = "Projects"
            st.session_state[_navigation_mode_state_key()] = "active"
            st.session_state[_navigation_secondary_state_key()] = "project_details"
            st.session_state[_navigation_tertiary_state_key()] = "browse"
        _set_object_workspace_view(st, "Summary")
        _record_recent_search_open(st, reference)
        st.rerun()
        return

    st.session_state["atlas_active_page"] = route
    if route == "Knowledge":
        _knowledge_navigation_defaults(st)
        _set_knowledge_navigation_selection(
            st,
            kind=selection_kind,
            page=route,
        )
        st.session_state[_navigation_primary_state_key()] = "Knowledge"
        st.session_state[_navigation_mode_state_key()] = "application"
        st.session_state[_navigation_secondary_state_key()] = _safe_text(
            _secondary_key_for_page("Knowledge", "application", route),
            "overview",
        )
        st.session_state[_navigation_tertiary_state_key()] = "browse"
    elif route in PROJECTS_LIBRARY_PAGES:
        st.session_state[_navigation_primary_state_key()] = "Projects"
        st.session_state[_navigation_mode_state_key()] = "library"
        st.session_state[_navigation_secondary_state_key()] = _safe_text(
            _secondary_key_for_page("Projects", "library", route),
            "overview",
        )
        st.session_state[_navigation_tertiary_state_key()] = "browse"
    else:
        st.session_state[_navigation_primary_state_key()] = "Projects"
        st.session_state[_navigation_mode_state_key()] = "active"
        st.session_state[_navigation_secondary_state_key()] = _safe_text(
            _secondary_key_for_page("Projects", "active", route),
            "overview",
        )
        st.session_state[_navigation_tertiary_state_key()] = "browse"

    _set_context_selection(st, selection_kind, selection_data)
    _record_recent_search_open(st, reference)
    st.rerun()


